{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C07", "C13", "C16", "C02", "C06", "C30", "C37", "C42", "C52", "C53", "C57", "C59"],
  "contradictory_card_ids": ["C28", "C22", "C32"],
  "prediction_basis_card_ids": ["C07", "C13", "C42", "C06", "C52", "C53", "C57"],
  "claims": [
    {
      "claim": "The closest aryloxyacetic acid fused-ring analog with human data, FK788, had a calculated oral bioavailability of 55% in healthy volunteers (C07), affirmatively supporting F >= 20% for this chemotype; its rat value of 9.6% (C28) is species-specific context and does not overturn the human result.",
      "card_ids": ["C07", "C28"]
    },
    {
      "claim": "Etodolac, an ionizable carboxylic acid with a hydrophobic fused-ring system, has human absolute oral bioavailability of 0.80 (C13) and estimated near 1 (C16, C02), showing that acidic fused-ring molecules can achieve high F.",
      "card_ids": ["C13", "C16", "C02"]
    },
    {
      "claim": "Cicaprost, a prostacyclin analog with an ether-acetic acid side chain, had oral AUC0-inf 422 pg·h/ml versus IV 409 pg·h/ml (~100% bioavailability) in humans (C42), directly supporting high oral F for this structural class.",
      "card_ids": ["C42"]
    },
    {
      "claim": "Fed-state evidence supports high F: KNI-272 capsule post-prandial F was 36.4% at 6.6 mg/kg (C06) and 22.06% at 4 mg/kg (C30), and propranolol food increased F from 0.27 to 0.46 (C37).",
      "card_ids": ["C06", "C30", "C37"]
    },
    {
      "claim": "L4 solubility/permeability records for similar prostaglandin and aryloxy acids show adequate solubility (dinoprost 1.5 mg/mL, C52; octyloxy-hydroxybenzoic acid 0.85 mg/mL, C53) and measurable Caco-2 permeability (PGE2 Papp 5.0×10^-7 cm/s, C57), supporting the absorption component; no L4 record affirmatively demonstrates F < 20%.",
      "card_ids": ["C52", "C53", "C57"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C51", "C52", "C53", "C54", "C55", "C56", "C57", "C58", "C59", "C60", "C61", "C62"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "No fed-state-specific F data for the exact aryloxyacetic acid fused-ring chemotype; fed records are from KNI-272 (peptidomimetic) and propranolol (basic beta-blocker).",
    "Permeability and efflux status of the query are not directly measured; PGE2 Caco-2 Papp is moderate and pravastatin transporter data are unclear.",
    "Species for the query is not specified; if the target is rat, low rat F values for analogs (FK788 9.6%, S-propranolol 12%) would be more concerning.",
    "Dose and formulation effects on F for the query are unknown; L4 solubility at pH 10 (100 µg/mL for compound 1) may not reflect fed intestinal conditions."
  ],
  "decision_summary": "Predicted high (F >= 20%) because the most transferable human gold records—FK788 (55%), etodolac (80-100%), and cicaprost (~100%)—affirmatively support F >= 20%, and L4 solubility/permeability records for similar prostaglandin/aryloxy acids support adequate absorption. Low rat/syrup values are species/formulation-specific and do not overturn; the unfavorable logD prior is insufficient to predict low."
}

